message.content:
{
  "description": "The creature is a quadrupedal chimera shown in right-facing profile against a plain off-white background, with the overall body shape, fur, and proportions of a brown bear but extensively covered in glossy, beetle-like exoskeletal armor. The head, ears, muzzle, and paws are distinctly bear-like with dense brown fur, while the back, shoulders, hips, chest, and outer surfaces of all four limbs are overlaid with shiny, dark reddish-brown segmented plates. The underside and inner limbs show lighter tan, ribbed plating. A single glossy dark horn projects from the forehead between the ears, and a narrow segmented tail extends from the rear. The animal stands on all four paws with claws visible, and the armor has a hard, varnished appearance with visible segmentation and sutures.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with dense shaggy brown fur, a lighter tan muzzle, a large black nose with nostrils, small dark brown eyes, and a closed mouth with faint whiskers",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "a single glossy dark burgundy to black horn with a smooth, curved main tip pointing up and back and a smaller sharp forward-pointing tine near the base, with a shiny, hard beetle-horn texture",
      "where": "on the midline of the forehead on top of the head, between the two ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown bear ears with dense fur, slightly darker at the edges",
      "where": "on top of the head on either side of the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular bear-like legs covered in brown fur, with glossy dark reddish-brown segmented armor plates on the outer upper and lower surfaces and lighter tan ribbed plates with horizontal ridges on the inner and ventral surfaces; the forelegs have large shoulder plates and shin guards, the hindlegs have large hip plates and shin guards",
      "where": "under the body in quadrupedal stance, two forelegs under the chest and two hindlegs under the hips"
    },
    {
      "part": "feet",
      "looks_like": "four large bear paws with brown fur on top, broad pads underneath, and five long, curved, dark claws on each foot",
      "where": "at the bottom of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a narrow, tapering, segmented tail with glossy dark reddish-brown plates on top and lighter tan plates with small dark spines underneath, ending in two small pointed tips",
      "where": "extending from the rear of the body, curving slightly downward"
    },
    {
      "part": "plates",
      "looks_like": "extensive glossy, hard, dark reddish-brown segmented dorsal armor with visible sutures and gold-tan lines between segments, covering the back from the neck to the base of the tail in overlapping transverse bands, plus large smooth shoulder and hip shields, layered chest plates, and segmented shin plates; the ventral side and flanks have lighter tan, ribbed, softer-looking plates with a row of eight oval dark-rimmed openings along the side and smaller circular pits below",
      "where": "covering the dorsal back, sides of neck and chest, shoulders, hips, and outer surfaces of all four limbs, with lighter plating on the belly, inner limbs, and underside of tail"
    },
    {
      "part": "shell",
      "looks_like": "a continuous, domed, glossy carapace formed by the fused dorsal plates, with a varnished, beetle-elytra appearance and transverse segmentation",
      "where": "over the back and rump, from just behind the neck to the tail base"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
